import{_ as n,o as t,c as r,a3 as l}from"./chunks/framework.BZKbe9n2.js";const g=JSON.parse('{"title":"Rollen und Rechte","description":"","frontmatter":{},"headers":[],"relativePath":"de/general/roles.md","filePath":"de/general/roles.md"}'),a={name:"de/general/roles.md"};function d(i,e,s,o,u,h){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="rollen-und-rechte" tabindex="-1">Rollen und Rechte <a class="header-anchor" href="#rollen-und-rechte" aria-label="Permalink to &quot;Rollen und Rechte&quot;">​</a></h1><p>Jedes Konto hat eine Rolle. Die Bibliothek teilen sich alle; Einstellungen, Playlists, Favoriten und der Verlauf sind persönlich.</p><table tabindex="0"><thead><tr><th>Rolle</th><th>Darf</th></tr></thead><tbody><tr><td><strong>Hören</strong></td><td>die Bibliothek durchsehen und durchsuchen, im Browser und auf Lautsprechern hören, Zonen und Lautstärken verwalten, Titel und Alben herunterladen, Playlists, Favoriten und Verlauf führen</td></tr><tr><td><strong>Redaktion</strong></td><td>alles, was die Rolle Hören darf, und dazu Tags bearbeiten, Cover hochladen, Einträge der Prüfliste und Konflikte entscheiden, Erkennung und Qualitätsanalyse starten, Quelldienste durchsuchen und Alben bestellen</td></tr><tr><td><strong>Administrator</strong></td><td>alles, was die Redaktion darf, und dazu Benutzer verwalten, Server-Ordner importieren, Quelldienste, Zeitpläne und die Systempflege einrichten und Lautsprecher-Adressen eintragen</td></tr></tbody></table><p>Das erste Konto, angelegt bei der Einrichtung, ist Administrator. Administratoren legen weitere Konten unter <strong>Einstellungen</strong> an.</p><h2 id="personliche-daten" tabindex="-1">Persönliche Daten <a class="header-anchor" href="#personliche-daten" aria-label="Permalink to &quot;Persönliche Daten&quot;">​</a></h2><ul><li><strong>Playlists</strong> sind privat oder für alle geteilt. In einer geteilten Playlist darf jeder Titel hinzufügen, entfernen und umordnen; umbenennen, teilen und löschen darf nur, wem sie gehört.</li><li><strong>Favoriten</strong> und der <strong>Verlauf</strong> sind nur für dich sichtbar.</li><li><strong>Einstellungen</strong> wie die Sprache und die Bitrate gelten pro Benutzer und Gerät.</li></ul>',6)])])}const f=n(a,[["render",d]]);export{g as __pageData,f as default};
